choose.when:
(

        e.created_by = #{scope.userId}
        OR e.primary_responsible_user_id = #{scope.userId}
        OR EXISTS (
            SELECT 1
            FROM equipment_responsible_person scoped_person
            WHERE scoped_person.tenant_id = e.tenant_id
              AND scoped_person.equipment_id = e.id
              AND scoped_person.user_id = #{scope.userId}
              AND scoped_person.status = 1
              AND scoped_person.deleted = 0
        )
        OR EXISTS (
            SELECT 1
            FROM inspection_task scoped_inspection
            WHERE scoped_inspection.tenant_id = e.tenant_id
              AND scoped_inspection.equipment_id = e.id
              AND scoped_inspection.deleted = 0
              AND (
                  scoped_inspection.assignee_user_id = #{scope.userId}
                  OR EXISTS (
                      SELECT 1
                      FROM inspection_task_assignee scoped_assignee
                      WHERE scoped_assignee.tenant_id =
                            scoped_inspection.tenant_id
                        AND scoped_assignee.task_id =
                            scoped_inspection.id
                        AND scoped_assignee.user_id = #{scope.userId}
                  )
              )
        )
        OR EXISTS (
            SELECT 1
            FROM maintenance_task scoped_maintenance
            WHERE scoped_maintenance.tenant_id = e.tenant_id
              AND scoped_maintenance.equipment_id = e.id
              AND scoped_maintenance.assignee_user_id = #{scope.userId}
              AND scoped_maintenance.deleted = 0
        )


        OR


        e.organization_id IN

            #{organizationId}


)

mapper.select:
SELECT COALESCE(SUM(planned_date = CURRENT_DATE()), 0) AS due_today,
       COALESCE(SUM(task_status IN (
           'PENDING', 'IN_PROGRESS', 'OVERDUE'
       )), 0) AS pending,
       COALESCE(SUM(
           task_status = 'OVERDUE'
           OR (
               task_status NOT IN ('COMPLETED', 'CANCELLED', 'VOIDED')
               AND due_time < CURRENT_TIMESTAMP(3)
           )
       ), 0) AS overdue,
       COALESCE(SUM(
           task_status = 'COMPLETED'
           AND DATE(completed_time) = CURRENT_DATE()
       ), 0) AS completed_today
FROM inspection_task task
WHERE task.tenant_id = #{tenantId}
  AND task.deleted = 0
  AND (
      task.assignee_user_id = #{userId}
      OR EXISTS (
          SELECT 1
          FROM inspection_task_assignee assignee
          WHERE assignee.tenant_id = task.tenant_id
            AND assignee.task_id = task.id
            AND assignee.user_id = #{userId}
      )
  )

SELECT COALESCE(SUM(planned_date = CURRENT_DATE()), 0) AS due_today,
       COALESCE(SUM(task_status IN (
           'PENDING', 'IN_PROGRESS', 'PAUSED',
           'PENDING_CONFIRMATION', 'OVERDUE'
       )), 0) AS pending,
       COALESCE(SUM(
           task_status = 'OVERDUE'
           OR (
               task_status NOT IN ('COMPLETED', 'CANCELLED', 'VOIDED')
               AND due_time < CURRENT_TIMESTAMP(3)
           )
       ), 0) AS overdue,
       COALESCE(SUM(
           task_status = 'COMPLETED'
           AND DATE(completed_time) = CURRENT_DATE()
       ), 0) AS completed_today
FROM maintenance_task task
WHERE task.tenant_id = #{tenantId}
  AND task.deleted = 0
  AND (
      task.assignee_user_id = #{userId}
      OR EXISTS (
          SELECT 1
          FROM maintenance_task_collaborator collaborator
          WHERE collaborator.tenant_id = task.tenant_id
            AND collaborator.task_id = task.id
            AND collaborator.user_id = #{userId}
      )
  )
